'use strict';
const app=document.querySelector('#app');
const questions=window.GodsData.questions,gods=window.GodsData.gods,score=window.GodsData.score;
let answers=[],step=0,result=0,cardUrl='',cardPath='',sharing=false,saving=false;
let platformVersion=0,interactionStarted=false;
function api(){return window.xhs && window.xhs.miniTool;}
function on(selector,handler,event){const el=document.querySelector(selector);if(el)el.addEventListener(event||'click',handler);}
function validAnswers(a){return Array.isArray(a)&&a.length===6&&a.every(v=>Number.isInteger(v)&&v>=0&&v<4);}
async function initPlatform(){
 const tool=api();let launch=window.xhs&&window.xhs.launchOptions;
 try{if((!launch||!launch.miniToolEnv)&&tool&&typeof tool.getLaunchOptions==='function')launch=await tool.getLaunchOptions();}catch(e){}
 platformVersion=Math.floor(Number(launch&&launch.miniToolEnv&&launch.miniToolEnv.buildVersion||0)/1000);
 if(platformVersion>=9490&&tool&&typeof tool.getWindowInfo==='function'){
  try{const info=await tool.getWindowInfo();const buttons=info.menuButtons||{};let bottom=0;Object.keys(buttons).forEach(k=>{if(buttons[k])bottom=Math.max(bottom,Number(buttons[k].bottom)||0)});if(bottom)document.documentElement.style.setProperty('--host-top',Math.min(bottom+10,180)+'px');}catch(e){}
 }
 let a;
 try{if(platformVersion>=9460&&tool&&typeof tool.getStorage==='function'){const r=await tool.getStorage({key:'little-gods-v1'});a=JSON.parse(r.data||'null');}else a=JSON.parse(localStorage.getItem('little-gods-v1')||'null');}catch(e){}
 if(validAnswers(a)&&!interactionStarted){answers=a;home();}
}
async function saveAnswers(a){try{const tool=api();if(platformVersion>=9460&&tool&&typeof tool.setStorage==='function')await tool.setStorage({key:'little-gods-v1',data:JSON.stringify(a)});else localStorage.setItem('little-gods-v1',JSON.stringify(a));}catch(e){/* Result remains usable without persistent storage. */}}
function loadComics(){const box=document.querySelector('.story-box'),gallery=document.querySelector('#comic-gallery');if(box&&box.open&&gallery&&!gallery.children.length){gallery.innerHTML=[1,2,3,4].map(n=>'<img src="./assets/comic-0'+n+'.jpg" alt="许愿乌龟漫画第'+n+'页">').join('');}}
function mascot(id=0){const colors=['#b4ce91','#b3cbd6','#c7b6db','#e7b985','#c4b8d9','#ecc97a'];const extras=[`<path d="M90 169 Q140 226 190 169Z" fill="#e78b80"/><path d="M90 169 Q140 226 190 169" fill="none" stroke="#719662" stroke-width="9"/><path d="M121 178l2 5m17-2v5m17-8-2 5"/>`,`<rect x="96" y="160" width="88" height="44" rx="9" fill="#eff3dd"/><path d="M108 173h64m-55 31v10m47-10v10"/>`,`<rect x="116" y="146" width="49" height="67" rx="7" fill="#f9f3df" transform="rotate(8 140 180)"/><path d="m132 169 18 18m0-18-18 18" stroke="#b56b58"/>`,`<path d="M92 171h96q-8 44-48 44t-48-44" fill="#f7f1d9"/><path d="M108 171q8-17 16 0t16 0t16 0t16 0" stroke="#d5a452"/><path d="m166 156 17-28m-6 31 17-28"/>`,`<rect x="80" y="159" width="120" height="52" rx="22" fill="#f9f5e7"/><path d="m105 177 9 6-9 6m60-12-9 6 9 6"/><path d="M204 72h19l-18 20h20" stroke="#8e7da6"/>`,`<path d="m105 184 2-32 22 15q12-4 22 0l22-15 2 32q3 32-35 32t-35-32" fill="#e9bd74"/><path d="m122 186 4 1m28-1 4 1m-22 8 4 3 4-3"/>`];return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 260" role="img" aria-label="手绘小神仙"><g stroke="#3c4939" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><ellipse cx="140" cy="236" rx="76" ry="9" fill="#394f3510" stroke="none"/><path d="M82 153q-22 30-8 67h132q13-42-10-67" fill="${colors[id]}"/><path d="M116 215v17m48-17v17"/><path d="M109 234h15m32 0h15"/><path d="M93 88q-20-2-22 19-5 16 8 28l-5 18 22-4m88-61q20-2 22 19 5 16-8 28l5 18-22-4" fill="#fff9e7"/><ellipse cx="140" cy="117" rx="52" ry="49" fill="#fff4d6"/><path d="M91 92q11-32 49-32t49 32" fill="#fff9e7"/><path d="M123 67q-11-27 12-33 21-6 23 14 0 12-14 14" fill="#fff9e7"/><ellipse cx="140" cy="31" rx="39" ry="9" fill="none" stroke="#c7a45a"/><path d="M118 117v5m44-5v5"/><path d="M134 130q6 6 12 0" fill="none"/><ellipse cx="108" cy="130" rx="9" ry="5" fill="#ebaf9b" stroke="none"/><ellipse cx="172" cy="130" rx="9" ry="5" fill="#ebaf9b" stroke="none"/>${extras[id]}<path d="M83 171q11-13 22 0m70 0q11-13 22 0" fill="none"/><path d="m42 89 3-8 3 8 8 3-8 3-3 8-3-8-8-3Z" fill="#e5c26a" stroke="none"/><path d="m226 126 3-8 3 8 8 3-8 3-3 8-3-8-8-3Z" fill="#e5c26a" stroke="none"/></g></svg>`}
function show(html){app.innerHTML=html;if(app.firstElementChild)app.firstElementChild.classList.add('fade');window.scrollTo(0,0);}
function home(){show(`<section class="home"><div class="eyebrow">THE LITTLE GODS OFFICE · 人间分处</div><h1>大愿望暂时缺货，<br><span class="underline">小福气正在派送。</span></h1><p class="subtitle">听说，每个人身边都跟着一位<br>经费有限、但很想照顾你的小神仙。</p><div class="hero-art"><span class="float-note">一块钱的工作量？</span><img class="hero-turtle" src="./assets/icon.jpg" alt="许愿池的乌龟正在审核你的愿望"><span class="float-note right">小本神仙 · 量力保佑</span></div><button class="primary" id="start">查查谁在偷偷管我 <span aria-hidden="true">→</span></button><div class="home-stats"><span>✎ 6 道小选择</span><span>◷ 约 1 分钟</span><span>♡ 6 位小神仙</span></div>${answers.length===6?'<button class="text-btn" id="last">查看我上次领到的神仙 ↗</button>':''}<details class="story-box"><summary>🐢 许愿被退款？点开看完整漫画</summary><div id="comic-gallery"></div></details><p class="section-label">本期在岗神仙 / 编制有限 · 心意管够</p><div class="roster">${gods.map(g=>`<div><span>${g.icon}</span>${g.name}</div>`).join('')}</div><p class="micro">免费测，免费出图，神仙不收加班费。</p></section>`);document.querySelector('#start').addEventListener('click',()=>{interactionStarted=true;answers=[];step=0;quiz()});on('#last',()=>showResult(score(answers)));on('.story-box',loadComics,'toggle');}
function quiz(){const q=questions[step];show(`<section><div class="step-top"><button id="back" class="text-btn">← ${step?'上一题':'办事大厅'}</button><span>申请进度 <b>${String(step+1).padStart(2,'0')}</b> / 06</span></div><div class="progress"><div style="width:${(step+1)/6*100}%"></div></div><div class="question-sheet"><span class="eyebrow">小福气申请表 · 第 ${step+1} 页</span><h1>${q[0]}</h1><div class="options">${q[1].map((a,i)=>`<button class="option ${answers[step]===i?'selected':''}" data-i="${i}" aria-pressed="${answers[step]===i}"><b>${'ABCD'[i]}</b><span>${a}</span></button>`).join('')}</div><button class="primary next" id="next" ${answers[step]===undefined?'disabled':''}>${step===5?'提交申请，看看谁接单':'填好了，下一题'} →</button></div><p class="hint">凭第一感觉选。放心，神仙不查征信。</p></section>`);document.querySelector('#back').addEventListener('click',()=>{if(step){step--;quiz()}else home()});document.querySelectorAll('.option').forEach(b=>b.addEventListener('click',()=>{answers[step]=Number(b.dataset.i);document.querySelectorAll('.option').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b))});document.querySelector('#next').disabled=false;}));document.querySelector('#next').addEventListener('click',()=>{if(answers[step]===undefined)return;if(step<5){step++;quiz()}else finish()});}
function finish(){result=score(answers);saveAnswers(answers);show(`<section class="loading">${mascot(result)}<h1>正在翻找你的香火档案…</h1><p>经费虽少，这单认真接。</p></section>`);setTimeout(()=>{if(document.querySelector('.loading'))showResult(result)},1300)}
function showResult(id){result=id;const g=gods[id];show(`<section style="--god-color:${g.color}"><div class="step-top"><button class="text-btn" id="home">← 办事大厅</button><span>档案已盖章 · 请本人签收</span></div><div class="result-ticket result-head"><div class="ticket-top"><span>守护神派遣档案 / NO. 00${id+1}</span><span class="stamp">分配成功</span></div><div class="result-portrait">${mascot(id)}</div><p class="eyebrow">正在偷偷保佑你的是</p><h1>${g.name}</h1><div class="job">${g.job}</div><div class="budget">本月可支配经费 <b>¥ ${g.budget}</b></div><div class="result-quote">“${g.quote}”</div></div><div class="result-story">${g.story.map(p=>`<p>${p}</p>`).join('')}</div><div class="note"><small>✎ 它偷偷塞给你的纸条</small>${g.note}</div><div class="luck"><strong>✦ 今天的小福报，请查收</strong>${g.luck}</div><div class="actions"><button class="primary" id="make-card">带我的神仙出去见见世面 ↗</button><button class="secondary" id="copy">分享测试，查查朋友归谁管</button><button class="text-btn" id="again">重新填一份申请 ↻</button></div><div class="signoff">发大财的申请还在楼上审批。<br>你今天这点小事，它先接了。</div></section>`);document.querySelector('#home').addEventListener('click',home);document.querySelector('#again').addEventListener('click',()=>{interactionStarted=true;answers=[];step=0;quiz()});document.querySelector('#copy').addEventListener('click',()=>shareTool('card'));document.querySelector('#make-card').addEventListener('click',createCard);}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',3000)}
function imageOf(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src;});}
function roundBox(x,l,t,w,h,r){x.moveTo(l+r,t);x.lineTo(l+w-r,t);x.quadraticCurveTo(l+w,t,l+w,t+r);x.lineTo(l+w,t+h-r);x.quadraticCurveTo(l+w,t+h,l+w-r,t+h);x.lineTo(l+r,t+h);x.quadraticCurveTo(l,t+h,l,t+h-r);x.lineTo(l,t+r);x.quadraticCurveTo(l,t,l+r,t);}
function textLines(x,text,y,maxWidth,lineHeight){for(const p of text.split('\n')){let line='';for(const ch of p){if(x.measureText(line+ch).width>maxWidth){x.fillText(line,450,y);y+=lineHeight;line='';}line+=ch;}x.fillText(line,450,y);y+=lineHeight;}return y;}
async function createCard(){
 const b=document.querySelector('#make-card');b.disabled=true;b.textContent='神仙正在盖章…';
 try{
  if(document.fonts&&document.fonts.ready)await document.fonts.ready;
  const g=gods[result],c=document.createElement('canvas');c.width=900;c.height=1200;const x=c.getContext('2d');
  x.fillStyle='#f5f0df';x.fillRect(0,0,900,1200);x.fillStyle='#fffcf1';x.beginPath();roundBox(x,40,40,820,1120,28);x.fill();x.strokeStyle='#cdd1bd';x.lineWidth=2;x.stroke();
  x.fillStyle='#42604b';x.font='bold 25px sans-serif';x.fillText('小本神仙办事处',85,105);x.font='18px sans-serif';x.fillText('守护神派遣档案 / NO. 00'+(result+1),85,145);
  const portrait=await imageOf('./assets/icon.jpg');x.save();x.beginPath();x.arc(450,335,145,0,Math.PI*2);x.clip();x.drawImage(portrait,305,190,290,290);x.restore();
  x.textAlign='center';x.fillStyle='#717968';x.font='23px sans-serif';x.fillText('正在偷偷保佑我的是',450,540);x.fillStyle='#303b32';x.font='bold 57px sans-serif';x.fillText(g.name,450,615);
  x.font='23px sans-serif';x.fillText('本月可支配经费 ¥ '+g.budget,450,670);x.setLineDash([7,7]);x.beginPath();x.moveTo(80,710);x.lineTo(820,710);x.stroke();x.setLineDash([]);
  x.font='bold 30px sans-serif';textLines(x,g.card,780,720,47);x.font='25px sans-serif';x.fillStyle='#42604b';x.fillText('大的正在想办法，小的先给你安排上。',450,1000);x.font='20px sans-serif';x.fillText('来「小本神仙办事处」查查你的天庭人脉',450,1050);x.font='16px sans-serif';x.fillStyle='#717968';x.fillText('趣味自我探索 · 非心理诊断 · 免费测试',450,1110);
  cardUrl=c.toDataURL('image/png');cardPath='';document.querySelector('#card-image').src=cardUrl;openShare();
 }catch(e){console.error('card generation',e);toast('分享卡生成失败：'+(e.message||String(e))); }finally{b.disabled=false;b.textContent='带我的神仙出去见见世面 ↗';}
}
function openShare(){document.querySelector('#share-dialog').hidden=false;document.body.classList.add('modal-open');document.querySelector('.close').focus();}
function closeShare(){document.querySelector('#share-dialog').hidden=true;document.body.classList.remove('modal-open');const b=document.querySelector('#make-card');if(b)b.focus();}
async function mediaPath(){const tool=api();if(!cardPath&&tool&&typeof tool.writeTempFile==='function'){const r=await tool.writeTempFile({data:cardUrl});cardPath=r.filePath;}return cardPath||cardUrl;}
async function saveCard(){
 if(saving||!cardUrl)return;const tool=api();
 if(platformVersion<9420||!tool||typeof tool.saveImageToPhotosAlbum!=='function'){toast('请在小红书 App 中扫码预览并保存图片（9.42及以上）。');return;}
 saving=true;const b=document.querySelector('#download');b.disabled=true;
 try{await tool.saveImageToPhotosAlbum({filePath:await mediaPath()});toast('分享卡已保存到相册。');}catch(e){toast('未能保存，请检查相册权限后重试。');}finally{saving=false;b.disabled=false;}
}
async function shareTool(type){
 if(sharing)return;const tool=api();
 if(platformVersion<9530||!tool||typeof tool.share!=='function'){toast('请在小红书9.53及以上版本全屏打开，使用站内分享。');return;}
 sharing=true;
 try{const options={type:type};if(type==='image'){if(!cardUrl)return;options.image_resource=await mediaPath();}await tool.share(options);}catch(e){const code=Number(e.errCode);toast(code===15502?'请在手机全屏打开小工具后分享；电脑预览暂不支持。':code===15503?'今天分享次数已达上限，明天再来。':'暂时无法打开分享面板，请重试。');}finally{sharing=false;}
}
on('.close',closeShare);on('#download',saveCard);on('#native-share',()=>shareTool('image'));on('#share-tool',()=>shareTool('card'));on('#brand',e=>{e.preventDefault();interactionStarted=true;home();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeShare();});
home();initPlatform();
